window.MACHINE_2025GA={"title":"Machine-2025Ga","note":"The memory dump in the exam PDF is clipped at the right edge; addresses 08–14 are not legible there. The three cycles below only read addresses 00–05, so the questions are still answerable.","mem":[["00","22"],["01","9C"],["02","93"],["03","12"],["04","B3"],["05","0E"],["06","32"],["07","0E"]],"regs":[["PC","00"],["R0","36"],["R1","AA"]],"ops":[["1","RXY","LOAD register R from the memory cell at address XY"],["2","RXY","LOAD register R with the value XY"],["3","RXY","STORE register R into the memory cell at address XY"],["4","0RS","MOVE register R to register S"],["5","RST","ADD S and T as two’s complement → R"],["6","RST","ADD S and T as floating point → R"],["7","RST","OR S and T → R"],["8","RST","AND S and T → R"],["9","RST","XOR S and T → R"],["A","R0X","ROTATE R one bit right, X times (circular)"],["B","RXY","JUMP to XY if register R equals register 0"],["C","000","HALT"]],"arch":"16 registers (0x0–0xF), one byte each. 256 memory cells, addresses 0x00–0xFF. Every instruction is two bytes: 4 bits of op-code, 12 bits of operand."};
